--
-- Name: Archivo; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public."Archivo" (
    id uuid NOT NULL,
    "tenantId" uuid NOT NULL,
    scope public."ArchivoScope" NOT NULL,
    key text NOT NULL,
    "nombreOriginal" text NOT NULL,
    "mimeType" text NOT NULL,
    bytes bigint DEFAULT 0 NOT NULL,
    hash text,
    estado public."ArchivoEstado" DEFAULT 'PENDIENTE'::public."ArchivoEstado" NOT NULL,
    publico boolean DEFAULT false NOT NULL,
    descripcion text,
    "subidoPorId" uuid,
    "eliminadoEl" timestamp(3) without time zone,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    "clienteId" uuid,
    "ordenId" uuid,
    "ordenItemId" uuid,
    "cotizacionId" uuid,
    "comprobanteId" uuid,
    "cobroId" uuid,
    "productoId" uuid,
    "proveedorId" uuid,
    generado boolean DEFAULT false NOT NULL,
    "multipartUploadId" text,
    "autogeneradoPor" text,
    "egresoId" uuid,
    CONSTRAINT "Archivo_scope_fk_coherente" CHECK ((((scope = 'CLIENTE'::public."ArchivoScope") = ("clienteId" IS NOT NULL)) AND ((scope = 'ORDEN'::public."ArchivoScope") = ("ordenId" IS NOT NULL)) AND ((scope = 'ORDEN_ITEM'::public."ArchivoScope") = ("ordenItemId" IS NOT NULL)) AND ((scope = 'COMPROBANTE'::public."ArchivoScope") = ("comprobanteId" IS NOT NULL)) AND ((scope = 'COBRO'::public."ArchivoScope") = ("cobroId" IS NOT NULL)) AND ((scope = 'PRODUCTO'::public."ArchivoScope") = ("productoId" IS NOT NULL)) AND ((scope = 'PROVEEDOR'::public."ArchivoScope") = ("proveedorId" IS NOT NULL)) AND (("cotizacionId" IS NULL) OR (scope = ANY (ARRAY['COTIZACION'::public."ArchivoScope", 'ORDEN'::public."ArchivoScope", 'ORDEN_ITEM'::public."ArchivoScope"]))) AND ((scope <> 'COTIZACION'::public."ArchivoScope") OR ("cotizacionId" IS NOT NULL))))
);


ALTER TABLE public."Archivo" OWNER TO postgres;

